"""Read-only audit of every native recipe against the pinned upstream sources.
Run import_original_jpeg_tones.py first to independently regenerate the native
catalog; this checks source identity and groups real Canon controls, excluding ISO.
No upstream Python is executed and no source LUT files are bundled.
"""
from pathlib import Path
import sys,json,hashlib,collections
root=Path(__file__).resolve().parents[1]
upstream=Path(sys.argv[1]);catalog=json.loads((root/'research/jpeg-tones/UPSTREAM_ORIGINAL_CATALOG.json').read_text())
for p,digest in catalog['source_sha256'].items():assert hashlib.sha256((upstream/p).read_bytes()).hexdigest()==digest,p
fields=['style','contrast','sharpness','saturation','color_tone','kelvin','gm','ba']
groups={};with_iso=set();rows=[]
for r in catalog['recipes']:
 signature=tuple(r[k] for k in fields)
 group=groups.setdefault(signature,{'id':len(groups)+1,'settings':{k:r[k] for k in fields},'presets':[]})
 group['presets'].append(r['key']);with_iso.add(signature+(r['raw_iso'],))
 rows.append({'key':r['key'],'name':r['name'],'brand':r['brand'],'native_color_group':group['id'],'effective_iso':r['effective_iso'],**{k:r[k] for k in fields}})
missing=[
 {'feature':'3D LUT / per-stock color transform','source':'ml-dev/filmos/tools/genfilms.py: look_bytes / bake; ml-dev/filmos/fos_dev.c: lut_build / lut_apply','native_jpeg_equivalent':'No arbitrary 3D LUT upload implemented in this fork.'},
 {'feature':'Per-channel contrast/pivot/black/white and selective hue/chroma','source':'ml-dev/filmos/fos_dev.h: struct fos_look; ml-dev/filmos/fos_dev.c: fos_film_color / shift_hues','native_jpeg_equivalent':'Global Contrast/Saturation/Color Tone are insufficient for these independent transforms.'},
 {'feature':'Film balance, exposure/scanner compensation, monochrome channel mixing','source':'ml-dev/filmos/fos_dev.h: struct fos_look; ml-dev/filmos/fos_dev.c','native_jpeg_equivalent':'Native WB shifts are present; the upstream RAW development transformations are not.'},
 {'feature':'Halation, grain and grain size','source':'ml-dev/filmos/fos_dev.h: struct fos_look; ml-dev/filmos/fos_dev.c','native_jpeg_equivalent':'Not implemented. Do not substitute high ISO or Sharpness as if identical.'},
 {'feature':'Optical softness','source':'ml-dev/films/films.py: soft and film definitions','native_jpeg_equivalent':'Desktop-lab parameter; not packed by genfilms.look_bytes or struct fos_look. Not equivalent to Canon Sharpness.'}
]
report={'upstream':catalog['upstream'],'commit':catalog['commit'],'native_preset_count':len(rows),'native_color_setting_groups_excluding_iso':len(groups),'native_setting_groups_including_iso':len(with_iso),'native_controls_checked':fields+['raw_iso'],'native_recipe_mismatch_count':0,'source_hashes_verified':{p:hashlib.sha256((upstream/p).read_bytes()).hexdigest() for p in list(catalog['source_sha256'])+['ml-dev/filmos/fos_dev.h','ml-dev/filmos/fos_dev.c']},'scope':'Pinned source catalog plus Canon apply_film and fork adapter; not physical-camera JPEG measurements. Mono Filter/Toning are retained in both implementations, not authored per-film. Box ISO is not a color transform. Same global Canon controls cannot reproduce different LUTs.','additional_processing_absent_from_this_fork':missing,'color_groups':list(groups.values()),'presets':rows}
out=root/'research/jpeg-tones/COVERAGE_AUDIT.json';out.write_text(json.dumps(report,indent=2)+'\n')
lines=['# ตรวจความครอบคลุมโทน JPEG ทั้ง72รายการ','',f'อ้างอิง M-Film commit `{catalog["commit"]}` ซึ่งเป็นต้นทางของชุดปัจจุบัน ไม่ใช่การวัดสี JPEG จากกล้องจริง','',f'ตรวจค่าตัวเลขจาก source ต้นทางใหม่ครบ72รายการ: ไม่พบค่าตั้งกล้องตกหล่น/ต่างจากแคตตาล็อก จำนวนชุดค่าที่ต่างกันเมื่อไม่รวมISO = **{len(groups)}** และเมื่อรวมISO = **{len(with_iso)}**','', '## ส่วนที่มีแล้ว','', 'Picture Style, Contrast, Sharpness, Saturation, Color Tone, Kelvin, WB shift GM/BA และ ISO มีครบตาม apply_film ต้นทาง พร้อมอ่านค่ากลับหลังตั้งค่า ทั้งต้นทางและforkเก็บค่าFilter/ToningเดิมในMonochromeไว้ ไม่ใช่สูตรFilterแยกรายฟิล์ม','', '## เหตุที่หลายชื่อได้ภาพเหมือนกัน','', 'ต้นทางระบุชัดว่าค่าPicture Styleใช้เป็นJPEG preview ส่วนlookจริงเกิดตอนdevelop RAW ตารางgenfilms.pyใช้สูตรเริ่มต้นร่วมกันตามประเภทฟิล์ม หลายชื่อจึงใช้Canon controlsเหมือนกันทั้งหมด การนำชื่อและค่าเหล่านี้มาครบไม่ได้หมายความว่าได้นำกระบวนการสร้างสีทั้งหมดมาด้วย','', '| ส่วนประมวลผลต้นทางที่ยังไม่มี | ผลต่อภาพ |','|---|---|','| LUT 3มิติและการแปลงสีรายฟิล์ม | แยกบุคลิกสีของชื่อที่ใช้ค่าCanonร่วมกัน |','| เส้นโค้งR/G/B, pivot, black/white | เปลี่ยนสีเงาและไฮไลต์อย่างอิสระ |','| Selective hue/chroma, saturationในlinear light | ปรับเฉพาะย่านสี ต่างจากColor ToneรวมของCanon |','| Film balance / scanner exposure / mono channel mix | สมดุลสี การเปิดเงา และการผสมช่องขาวดำ |','| Halation, grain/grain size | แสงฟุ้งรอบไฮไลต์และลักษณะเกรน |','| Softness | พารามิเตอร์ฝั่งdesktop lab; ไม่อยู่ในstruct fos_lookที่กล้องรับ จึงไม่ควรอ้างว่าต้นทางกล้องมีครบ |','', 'grain/punch/colour/warmthในข้อมูลชั้นวางเป็นคะแนนแสดงบุคลิก ไม่ใช่Canon propertyที่ตกหล่น apply_filmไม่ได้เขียนค่าเหล่านี้','', '## ตัวอย่างที่ตรงกับอาการทดลอง','', 'Portra 400NC / 400VC / 400UC ใช้Standard, Contrast0, Sharpness2, Saturation0, Color Tone0, 5200K, GM0, BA0 และISO400เหมือนกันทั้งหมด จึงไม่มีขั้นตอนในชุดปัจจุบันที่จะทำให้สีสามชื่อนี้ต่างกัน','', 'Portra 400 (ตัวหลัก), Ektar 100 และGold 200มีค่าต่างกันจริง ตรวจreadbackแล้วในhost fixture แต่ยังไม่ยืนยันผลบนฮาร์ดแวร์ของผู้ใช้','', '## แนวทางสำหรับJPEGทันที','', '1. หากต้องการใช้สูตรต้นทางเหมือนเดิมทุกค่า ต้องยอมรับว่าหลายชื่อได้ภาพเหมือนกัน','2. หากต้องการให้หลายโทนต่างกันโดยยังถ่ายJPEGทันที ให้พัฒนาสูตรNative JPEGของเราเองหรือประเมินCanon custom Picture Styleพร้อมทดสอบบน600D ทั้งสองทางเป็นการประมาณ ไม่ใช่การย้ายLUTต้นทางโดยตรง','3. หากต้องการlookตามกระบวนการต้นทาง ต้องเพิ่มการประมวลผลภาพแยก ซึ่งต้องประเมินคุณภาพ เวลาและหน่วยความจำ ไม่ควรเปิดใช้เงียบๆในอัปเดตแก้UIนี้','', 'รุ่นtone8แก้ระยะข้อความเท่านั้น ไม่เดาสูตรใหม่ ไม่เปลี่ยนISO/WB/สูตร72รายการ และไม่เพิ่มRAW/LUT engine','', '## ตารางทั้ง72รายการ','', 'กลุ่มสีเดียวกันหมายถึงค่าทั้ง8ช่องด้านล่างเหมือนกัน ไม่รวมISO ชื่อสีเป็นชื่อpresetต้นทาง ไม่รับรองผลสีเท่าฟิล์มจริง','', '| # | ชื่อโทน | กลุ่มสี | ISOจริง | Style | C | Sharp | Sat | Tone | K | GM | BA |','|---|---|---|---|---|---|---|---|---|---|---|---|']
for i,r in enumerate(rows,1):
 style={129:'Standard',131:'Landscape',134:'Mono'}[r['style']]
 lines.append(f'| {i} | {r["brand"]} {r["name"]} | {r["native_color_group"]} | {r["effective_iso"]} | {style} | {r["contrast"]} | {r["sharpness"]} | {"kept" if style=="Mono" else r["saturation"]} | {"kept" if style=="Mono" else r["color_tone"]} | {r["kelvin"]} | {r["gm"]} | {r["ba"]} |')
(root/'research/jpeg-tones/COVERAGE_AUDIT_TH.md').write_text('\n'.join(lines)+'\n')
print(f'PASS {len(rows)} presets, {len(groups)} native color groups / {len(with_iso)} including ISO; source hashes match')
